// @ts-nocheck
// SPDX-License-Identifier: BUSL-1.1
export function buildSharedOutputParametersSource(): string {
  return [
    "// Generated by OpenShapeForge Service Compiler.",
    "// Do not edit manually.",
    "",
    'import type { Field } from "@/generated/compiler/field-contract";',
    "",
    "/**",
    " * Stored shape: a record of field-key → boolean, where `true` means the",
    " * key is selected on the success-handle output. The canonical workflow",
    " * validator (`openshapeforge-workflow/src/canonical/entity-workflow.ts`) accepts",
    " * both this shape and legacy `string[]`; the normalizer below converts",
    " * either input into the canonical record form.",
    " */",
    "export type GeneratedEntityOutputParameterConfig = Record<string, boolean>;",
    "",
    "function collectFieldKeys(fields: readonly Field[]): string[] {",
    "  const result: string[] = [];",
    "  const seen = new Set<string>();",
    "  for (const field of fields) {",
    "    if (!field || typeof field.key !== \"string\") {",
    "      continue;",
    "    }",
    "    if (seen.has(field.key)) {",
    "      continue;",
    "    }",
    "    seen.add(field.key);",
    "    result.push(field.key);",
    "  }",
    "  return result;",
    "}",
    "",
    "function seedAllSelected(",
    "  supportedKeys: readonly string[],",
    "): GeneratedEntityOutputParameterConfig {",
    "  const result: GeneratedEntityOutputParameterConfig = {};",
    "  for (const key of supportedKeys) {",
    "    result[key] = true;",
    "  }",
    "  return result;",
    "}",
    "",
    "function cloneField(field: Field): Field {",
    "  return JSON.parse(JSON.stringify(field)) as Field;",
    "}",
    "",
    "function isCollectionField(field: Field | undefined): boolean {",
    "  if (!field) return false;",
    "  if (field.cardinality === \"collection\") return true;",
    "  const cardinality = field.cardinality;",
    "  if (!cardinality || typeof cardinality !== \"object\") return false;",
    "  return cardinality.max === \"unbounded\" || (typeof cardinality.max === \"number\" && cardinality.max > 1);",
    "}",
    "",
    "function getListItemsField(defaultOutputFields: readonly Field[]): Field | null {",
    "  return defaultOutputFields.find((field) => field.key === \"items\" && isCollectionField(field)) ?? null;",
    "}",
    "",
    "function getListCountField(defaultOutputFields: readonly Field[]): Field | null {",
    "  return defaultOutputFields.find((field) => field.key === \"count\") ?? null;",
    "}",
    "",
    "function getSingleListItemOutputFields(defaultOutputFields: readonly Field[]): Field[] {",
    "  const itemsField = getListItemsField(defaultOutputFields);",
    "  const item = itemsField?.item;",
    "  if (!item) {",
    "    return [];",
    "  }",
    "  if (item.valueType === \"object\" && !isCollectionField(item) && item.children?.length) {",
    "    return item.children.map(cloneField);",
    "  }",
    "  return [cloneField(item)];",
    "}",
    "",
    "function getManyListOutputFields(defaultOutputFields: readonly Field[]): Field[] {",
    "  const fields: Field[] = [];",
    "  const itemsField = getListItemsField(defaultOutputFields);",
    "  const countField = getListCountField(defaultOutputFields);",
    "  if (itemsField) {",
    "    fields.push(cloneField(itemsField));",
    "  }",
    "  if (countField) {",
    "    fields.push(cloneField(countField));",
    "  }",
    "  return fields;",
    "}",
    "",
    "export function getGeneratedEntityListOutputFieldsForHandle(",
    "  defaultOutputFields: readonly Field[],",
    "  handleId?: string,",
    "): Field[] {",
    "  if (handleId === \"none\") {",
    "    return [];",
    "  }",
    "  if (handleId === \"one\") {",
    "    return getSingleListItemOutputFields(defaultOutputFields);",
    "  }",
    "  if (handleId === \"many\") {",
    "    return getManyListOutputFields(defaultOutputFields);",
    "  }",
    "  return defaultOutputFields.map(cloneField);",
    "}",
    "",
    "function normalizeSelection(",
    "  value: unknown,",
    "  supportedKeys: readonly string[],",
    "): GeneratedEntityOutputParameterConfig {",
    "  const supported = new Set(supportedKeys);",
    "",
    "  if (Array.isArray(value)) {",
    "    const result: GeneratedEntityOutputParameterConfig = {};",
    "    for (const key of supportedKeys) {",
    "      result[key] = false;",
    "    }",
    "    let any = false;",
    "    for (const entry of value) {",
    "      if (typeof entry !== \"string\") continue;",
    "      const trimmed = entry.trim();",
    "      if (trimmed && supported.has(trimmed)) {",
    "        result[trimmed] = true;",
    "        any = true;",
    "      }",
    "    }",
    "    return any ? result : seedAllSelected(supportedKeys);",
    "  }",
    "",
    "  if (value && typeof value === \"object\") {",
    "    const record = value as Record<string, unknown>;",
    "    if (Array.isArray(record.keys)) {",
    "      // Legacy `{ keys: string[] }` shape — recurse on the inner array.",
    "      return normalizeSelection(record.keys, supportedKeys);",
    "    }",
    "    const result: GeneratedEntityOutputParameterConfig = {};",
    "    for (const key of supportedKeys) {",
    "      result[key] = false;",
    "    }",
    "    let anySupportedKey = false;",
    "    for (const [rawKey, enabled] of Object.entries(record)) {",
    "      const trimmed = typeof rawKey === \"string\" ? rawKey.trim() : \"\";",
    "      if (!trimmed || !supported.has(trimmed)) continue;",
    "      anySupportedKey = true;",
    "      if (enabled === true) {",
    "        result[trimmed] = true;",
    "      }",
    "    }",
    "    return anySupportedKey ? result : seedAllSelected(supportedKeys);",
    "  }",
    "",
    "  return seedAllSelected(supportedKeys);",
    "}",
    "",
    "/**",
    " * Builds the designer field that lets the author pick which of a node's",
    " * default output fields should end up on the success-handle output. The",
    " * field is an object group with one boolean child per available output",
    " * field — the renderer's existing `object` + `boolean` primitives produce",
    " * the labelled checkbox UX without a custom component.",
    " */",
    "export function buildGeneratedEntityOutputParametersField(",
    "  defaultOutputFields: readonly Field[],",
    "): Field {",
    "  const supportedKeys = collectFieldKeys(defaultOutputFields);",
    "  const children: Field[] = defaultOutputFields",
    "    .filter(",
    "      (field): field is Field =>",
    "        Boolean(field && typeof field.key === \"string\"),",
    "    )",
    "    .map((field) => ({",
    "      key: field.key,",
    "      valueType: \"boolean\",",
    "      label: field.label ?? { en: field.key, nl: field.key },",
    "      render: { component: \"Checkbox\" },",
    "    }));",
    "  return {",
    "    key: \"outputParameters\",",
    "    valueType: \"object\",",
    "    label: { en: \"Output parameters\", nl: \"Uitvoerparameters\" },",
    "    description: {",
    "      en: \"Which fields should be available on the success output of this node.\",",
    "      nl: \"Welke velden moeten beschikbaar zijn op de succes-uitgang van deze node.\",",
    "    },",
    "    children,",
    "    defaultValue: seedAllSelected(supportedKeys),",
    "  };",
    "}",
    "",
    "/**",
    " * Normalizes a stored `outputParameters` value into the canonical",
    " * `Record<string, boolean>` shape. Missing or empty input falls back to",
    " * \"all keys selected\". Both legacy `string[]` and `{ keys: string[] }`",
    " * shapes are accepted so existing seed/DB data continues to load.",
    " */",
    "export function normalizeGeneratedEntityOutputParameterConfig(",
    "  value: unknown,",
    "  defaultOutputFields: readonly Field[],",
    "): GeneratedEntityOutputParameterConfig {",
    "  const supportedKeys = collectFieldKeys(defaultOutputFields);",
    "  return normalizeSelection(value, supportedKeys);",
    "}",
    "",
    "/**",
    " * Returns the subset of `defaultOutputFields` the stored config selects.",
    " */",
    "export function getSelectedGeneratedEntityOutputFields(",
    "  outputParametersConfig: unknown,",
    "  defaultOutputFields: readonly Field[],",
    "): Field[] {",
    "  const selection = normalizeGeneratedEntityOutputParameterConfig(",
    "    outputParametersConfig,",
    "    defaultOutputFields,",
    "  );",
    "  return defaultOutputFields.filter((field) => {",
    "    if (!field || typeof field.key !== \"string\") return false;",
    "    return selection[field.key] === true;",
    "  });",
    "}",
    "",
  ].join("\n");
}
